// Three more example sentences per HSK 5-9 theme lesson (index = lesson - 1),
// built around the same theme vocabulary as mandarinThemeSentences.ts.
// Pinyin is generated from the Hanzi: npm run content:pinyin
export const extraThemeSentences: Partial<Record<MandarinLevelId, SentenceTuple[][]>> = {
  advanced: [
    [['在大城市里，邻居之间的人际关系往往比较冷淡。', 'Zài dà chéng shì lǐ, lín jū zhī jiān de rén jì guān xì wǎng wǎng bǐ jiào lěng dàn.', 'Di kota besar, hubungan antartetangga sering kali cukup renggang.'], ['为了减少通勤时间，他决定搬到公司附近。', 'Wèi le jiǎn shǎo tōng qín shí jiān, tā jué dìng bān dào gōng sī fù jìn.', 'Untuk mengurangi waktu perjalanan kerja, dia memutuskan pindah ke dekat kantor.'], ['城市化虽然带来了便利，但也让生活节奏越来越紧张。', 'Chéng shì huà suī rán dài lái le biàn lì, dàn yě ràng shēng huó jié zòu yuè lái yuè jǐn zhāng.', 'Urbanisasi memang membawa kemudahan, tetapi juga membuat ritme hidup semakin tegang.']],
    [['使用人脸识别技术时，必须考虑隐私保护的问题。', 'Shǐ yòng rén liǎn shí bié jì shù shí, bì xū kǎo lǜ yǐn sī bǎo hù de wèn tí.', 'Saat memakai teknologi pengenalan wajah, perlindungan privasi harus dipertimbangkan.'], ['企业不能为了利益而忽视伦理原则。', 'Qǐ yè bù néng wèi le lì yì ér hū shì lún lǐ yuán zé.', 'Perusahaan tidak boleh mengabaikan prinsip etika demi keuntungan.'], ['我们需要为新技术划清边界，降低可能的风险。', 'Wǒ men xū yào wèi xīn jì shù huà qīng biān jiè, jiàng dī kě néng de fēng xiǎn.', 'Kita perlu menetapkan batas yang jelas bagi teknologi baru untuk menekan risiko yang mungkin timbul.']],
    [['学校增加了很多实践课程，学生们很欢迎。', 'Xué xiào zēng jiā le hěn duō shí jiàn kè chéng, xué shēng men hěn huān yíng.', 'Sekolah menambah banyak mata pelajaran praktik, dan para siswa menyambutnya dengan baik.'], ['改革的效果需要几年时间才能看出来。', 'Gǎi gé de xiào guǒ xū yào jǐ nián shí jiān cái néng kàn chū lái.', 'Hasil reformasi baru bisa terlihat setelah beberapa tahun.'], ['网络资源为自主学习提供了更多可能。', 'Wǎng luò zī yuán wèi zì zhǔ xué xí tí gōng le gèng duō kě néng.', 'Sumber daya internet memberi lebih banyak kemungkinan untuk belajar mandiri.']],
    [['他做事很有责任感，老板非常信任他。', 'Tā zuò shì hěn yǒu zé rèn gǎn, lǎo bǎn fēi cháng xìn rèn tā.', 'Dia bekerja dengan rasa tanggung jawab yang tinggi, atasan sangat memercayainya.'], ['如果沟通不及时，团队合作就会出现问题。', 'Rú guǒ gōu tōng bù jí shí, tuán duì hé zuò jiù huì chū xiàn wèn tí.', 'Jika komunikasi tidak tepat waktu, kerja sama tim akan bermasalah.'], ['越来越多的年轻人拒绝无意义的加班。', 'Yuè lái yuè duō de nián qīng rén jù jué wú yì yì de jiā bān.', 'Semakin banyak anak muda menolak lembur yang tidak bermakna.']],
    [['环保不仅是政府的责任，也是每个人的责任。', 'Huán bǎo bù jǐn shì zhèng fǔ de zé rèn, yě shì měi gè rén de zé rèn.', 'Menjaga lingkungan bukan hanya tanggung jawab pemerintah, tetapi juga tanggung jawab setiap orang.'], ['这条河的污染问题已经得到了明显改善。', 'Zhè tiáo hé de wū rǎn wèn tí yǐ jīng dé dào le míng xiǎn gǎi shàn.', 'Masalah pencemaran sungai ini sudah membaik secara nyata.'], ['水资源短缺的地区更需要合理的政策。', 'Shuǐ zī yuán duǎn quē de dì qū gèng xū yào hé lǐ de zhèng cè.', 'Daerah yang kekurangan sumber daya air lebih membutuhkan kebijakan yang tepat.']],
    [['媒体有责任在报道前核实事实。', 'Méi tǐ yǒu zé rèn zài bào dào qián hé shí shì shí.', 'Media bertanggung jawab memverifikasi fakta sebelum memberitakan.'], ['有时候，偏见会让我们看不清真相。', 'Yǒu shí hòu, piān jiàn huì ràng wǒ men kàn bù qīng zhēn xiàng.', 'Kadang-kadang prasangka membuat kita tidak bisa melihat kebenaran dengan jelas.'], ['在转发消息之前，先想一想它会不会是谣言。', 'Zài zhuǎn fā xiāo xī zhī qián, xiān xiǎng yi xiǎng tā huì bu huì shì yáo yán.', 'Sebelum meneruskan pesan, pikirkan dulu apakah itu mungkin rumor.']],
    [['这个品牌的产品质量好，价格也合理。', 'Zhè ge pǐn pái de chǎn pǐn zhì liàng hǎo, jià gé yě hé lǐ.', 'Produk merek ini berkualitas baik dan harganya juga wajar.'], ['消费者越来越会比较不同产品的性价比。', 'Xiāo fèi zhě yuè lái yuè huì bǐ jiào bù tóng chǎn pǐn de xìng jià bǐ.', 'Konsumen semakin pandai membandingkan rasio harga dan kualitas berbagai produk.'], ['有些广告夸大了产品的效果。', 'Yǒu xiē guǎng gào kuā dà le chǎn pǐn de xiào guǒ.', 'Sebagian iklan melebih-lebihkan khasiat produk.']],
    [['学会说不，也是减轻压力的一种办法。', 'Xué huì shuō bù, yě shì jiǎn qīng yā lì de yì zhǒng bàn fǎ.', 'Belajar berkata tidak juga salah satu cara mengurangi tekanan.'], ['心理健康和身体健康同样重要。', 'Xīn lǐ jiàn kāng hé shēn tǐ jiàn kāng tóng yàng zhòng yào.', 'Kesehatan mental sama pentingnya dengan kesehatan fisik.'], ['早睡早起的习惯让我的精神好多了。', 'Zǎo shuì zǎo qǐ de xí guàn ràng wǒ de jīng shén hǎo duō le.', 'Kebiasaan tidur dan bangun lebih awal membuat semangat saya jauh lebih baik.']],
    [['很多年轻人通过社交媒体重新认识传统节日。', 'Hěn duō nián qīng rén tōng guò shè jiāo méi tǐ chóng xīn rèn shi chuán tǒng jié rì.', 'Banyak anak muda mengenal kembali hari raya tradisional lewat media sosial.'], ['全球化让不同文化之间的交流更加频繁。', 'Quán qiú huà ràng bù tóng wén huà zhī jiān de jiāo liú gèng jiā pín fán.', 'Globalisasi membuat pertukaran antarbudaya semakin sering.'], ['对家乡的认同感让他决定回国工作。', 'Duì jiā xiāng de rèn tóng gǎn ràng tā jué dìng huí guó gōng zuò.', 'Rasa keterikatan pada kampung halaman membuatnya memutuskan pulang untuk bekerja.']],
    [['就业情况是衡量经济健康的重要指标。', 'Jiù yè qíng kuàng shì héng liáng jīng jì jiàn kāng de zhòng yào zhǐ biāo.', 'Kondisi lapangan kerja adalah indikator penting kesehatan ekonomi.'], ['在通货膨胀时期，人们更关心物价的变化。', 'Zài tōng huò péng zhàng shí qī, rén men gèng guān xīn wù jià de biàn huà.', 'Pada masa inflasi, orang lebih memperhatikan perubahan harga.'], ['投资之前，一定要了解可能的风险。', 'Tóu zī zhī qián, yí dìng yào liǎo jiě kě néng de fēng xiǎn.', 'Sebelum berinvestasi, pastikan memahami risiko yang mungkin ada.']],
    [['这座城市的地铁票价比公交车稍微贵一点。', 'Zhè zuò chéng shì de dì tiě piào jià bǐ gōng jiāo chē shāo wēi guì yì diǎn.', 'Tarif kereta bawah tanah di kota ini sedikit lebih mahal daripada bus.'], ['为了缓解拥堵，政府限制了私家车的数量。', 'Wèi le huǎn jiě yōng dǔ, zhèng fǔ xiàn zhì le sī jiā chē de shù liàng.', 'Untuk mengurangi kemacetan, pemerintah membatasi jumlah mobil pribadi.'], ['方便的公共交通让很多人放弃了开车。', 'Fāng biàn de gōng gòng jiāo tōng ràng hěn duō rén fàng qì le kāi chē.', 'Transportasi umum yang praktis membuat banyak orang berhenti menyetir.']],
    [['算法会根据我们的习惯推荐内容。', 'Suàn fǎ huì gēn jù wǒ men de xí guàn tuī jiàn nèi róng.', 'Algoritme merekomendasikan konten berdasarkan kebiasaan kita.'], ['人工智能可以帮助医生更快地发现疾病。', 'Rén gōng zhì néng kě yǐ bāng zhù yī shēng gèng kuài de fā xiàn jí bìng.', 'Kecerdasan buatan dapat membantu dokter menemukan penyakit lebih cepat.'], ['缺少监管的技术可能带来严重的问题。', 'Quē shǎo jiān guǎn de jì shù kě néng dài lái yán zhòng de wèn tí.', 'Teknologi tanpa pengawasan dapat menimbulkan masalah serius.']],
    [['在中国，子女有赡养父母的义务。', 'Zài zhōng guó, zǐ nǚ yǒu shàn yǎng fù mǔ de yì wù.', 'Di Tiongkok, anak berkewajiban menafkahi orang tuanya.'], ['退休以后，很多老人参加社区活动。', 'Tuì xiū yǐ hòu, hěn duō lǎo rén cān jiā shè qū huó dòng.', 'Setelah pensiun, banyak lansia ikut kegiatan komunitas.'], ['社区养老中心让老人在家门口就能得到照顾。', 'Shè qū yǎng lǎo zhōng xīn ràng lǎo rén zài jiā mén kǒu jiù néng dé dào zhào gù.', 'Pusat layanan lansia di komunitas membuat lansia bisa dirawat dekat rumah.']],
    [['网课的最大优点是时间灵活。', 'Wǎng kè de zuì dà yōu diǎn shì shí jiān líng huó.', 'Kelebihan terbesar kelas daring adalah waktunya fleksibel.'], ['为了增加互动，老师常常让学生分组讨论。', 'Wèi le zēng jiā hù dòng, lǎo shī cháng cháng ràng xué shēng fēn zǔ tǎo lùn.', 'Untuk menambah interaksi, guru sering meminta siswa berdiskusi berkelompok.'], ['没有自律，再好的网课也没有用。', 'Méi yǒu zì lǜ, zài hǎo de wǎng kè yě méi yǒu yòng.', 'Tanpa disiplin diri, kelas daring sebagus apa pun tidak berguna.']],
    [['这个社区的图书馆全靠志愿者管理。', 'Zhè ge shè qū de tú shū guǎn quán kào zhì yuàn zhě guǎn lǐ.', 'Perpustakaan komunitas ini sepenuhnya dikelola relawan.'], ['公益不只是捐钱，也可以是捐出时间。', 'Gōng yì bù zhǐ shì juān qián, yě kě yǐ shì juān chū shí jiān.', 'Kegiatan sosial bukan hanya menyumbang uang, tetapi juga bisa menyumbang waktu.'], ['她把奉献社会当成自己的人生目标。', 'Tā bǎ fèng xiàn shè huì dàng chéng zì jǐ de rén shēng mù biāo.', 'Dia menjadikan pengabdian kepada masyarakat sebagai tujuan hidupnya.']],
    [['兴趣是最好的老师，也是选择职业的重要依据。', 'Xìng qù shì zuì hǎo de lǎo shī, yě shì xuǎn zé zhí yè de zhòng yào yī jù.', 'Minat adalah guru terbaik sekaligus dasar penting dalam memilih profesi.'], ['父母希望我找一份稳定的工作。', 'Fù mǔ xī wàng wǒ zhǎo yí fèn wěn dìng de gōng zuò.', 'Orang tua ingin saya mencari pekerjaan yang stabil.'], ['大学期间就应该开始做职业规划。', 'Dà xué qī jiān jiù yīng gāi kāi shǐ zuò zhí yè guī huà.', 'Perencanaan karier sebaiknya dimulai sejak masa kuliah.']],
    [['没有可靠的论据，论点就没有说服力。', 'Méi yǒu kě kào de lùn jù, lùn diǎn jiù méi yǒu shuō fú lì.', 'Tanpa bukti pendukung yang andal, argumen tidak meyakinkan.'], ['这首诗的含义需要反复读才能理解。', 'Zhè shǒu shī de hán yì xū yào fǎn fù dú cái néng lǐ jiě.', 'Makna puisi ini baru bisa dipahami setelah dibaca berulang kali.'], ['抽象的概念最好用具体的例子来解释。', 'Chōu xiàng de gài niàn zuì hǎo yòng jù tǐ de lì zi lái jiě shì.', 'Konsep abstrak sebaiknya dijelaskan dengan contoh konkret.']],
    [['两个段落之间需要自然的过渡。', 'Liǎng gè duàn luò zhī jiān xū yào zì rán de guò dù.', 'Di antara dua paragraf perlu transisi yang wajar.'], ['在正式场合，说话要注意用词。', 'Zài zhèng shì chǎng hé, shuō huà yào zhù yì yòng cí.', 'Dalam situasi resmi, pilihan kata harus diperhatikan.'], ['结论部分不要再提出新的观点。', 'Jié lùn bù fen bú yào zài tí chū xīn de guān diǎn.', 'Pada bagian kesimpulan jangan lagi mengajukan pendapat baru.']],
    [['重音放在不同的词上，句子的意思也会不同。', 'Zhòng yīn fàng zài bù tóng de cí shàng, jù zi de yì si yě huì bù tóng.', 'Jika tekanan diletakkan pada kata yang berbeda, makna kalimat pun berbeda.'], ['适当的停顿可以让听众有时间思考。', 'Shì dàng de tíng dùn kě yǐ ràng tīng zhòng yǒu shí jiān sī kǎo.', 'Jeda yang tepat memberi pendengar waktu untuk berpikir.'], ['流利不等于说得快，而是说得自然。', 'Liú lì bù děng yú shuō de kuài, ér shì shuō de zì rán.', 'Lancar bukan berarti berbicara cepat, melainkan berbicara dengan wajar.']],
    [['我把这个学期的进步都记在笔记本上。', 'Wǒ bǎ zhè ge xué qī de jìn bù dōu jì zài bǐ jì běn shàng.', 'Saya mencatat semua kemajuan semester ini di buku catatan.'], ['有了明确的目标，学习才有方向。', 'Yǒu le míng què de mù biāo, xué xí cái yǒu fāng xiàng.', 'Dengan target yang jelas, belajar menjadi terarah.'], ['定期反思可以帮助我们及时调整方法。', 'Dìng qī fǎn sī kě yǐ bāng zhù wǒ men jí shí tiáo zhěng fāng fǎ.', 'Refleksi rutin membantu kita menyesuaikan metode tepat waktu.']],
  ],
  proficiency: [
    [['没有问责机制，权力就容易被滥用。', 'Méi yǒu wèn zé jī zhì, quán lì jiù róng yì bèi làn yòng.', 'Tanpa mekanisme akuntabilitas, kekuasaan mudah disalahgunakan.'], ['公开预算信息是提高透明度的有效途径。', 'Gōng kāi yù suàn xìn xī shì tí gāo tòu míng dù de yǒu xiào tú jìng.', 'Membuka informasi anggaran adalah cara efektif meningkatkan transparansi.'], ['一项决定即使合法，也未必能赢得公共信任。', 'Yí xiàng jué dìng jí shǐ hé fǎ, yě wèi bì néng yíng dé gōng gòng xìn rèn.', 'Suatu keputusan, meskipun sah, belum tentu memperoleh kepercayaan publik.']],
    [['基因编辑技术不断挑战伦理边界。', 'Jī yīn biān jí jì shù bú duàn tiǎo zhàn lún lǐ biān jiè.', 'Teknologi penyuntingan gen terus menantang batas etika.'], ['算法偏见往往源于历史数据中的不平等。', 'Suàn fǎ piān jiàn wǎng wǎng yuán yú lì shǐ shù jù zhōng de bù píng děng.', 'Bias algoritme sering berasal dari ketidaksetaraan dalam data historis.'], ['减少技术依赖，才能保持人的主体性。', 'Jiǎn shǎo jì shù yī lài, cái néng bǎo chí rén de zhǔ tǐ xìng.', 'Hanya dengan mengurangi ketergantungan pada teknologi, subjektivitas manusia bisa terjaga.']],
    [['奖学金制度在一定程度上缓解了机会不均。', 'Jiǎng xué jīn zhì dù zài yí dìng chéng dù shàng huǎn jiě le jī huì bù jūn.', 'Sistem beasiswa sampai batas tertentu meredakan ketimpangan kesempatan.'], ['合理的资源分配是实现教育公平的前提。', 'Hé lǐ de zī yuán fēn pèi shì shí xiàn jiào yù gōng píng de qián tí.', 'Distribusi sumber daya yang wajar adalah prasyarat terwujudnya keadilan pendidikan.'], ['当阶层流动受阻时，社会的活力也会下降。', 'Dāng jiē céng liú dòng shòu zǔ shí, shè huì de huó lì yě huì xià jiàng.', 'Ketika mobilitas sosial terhambat, vitalitas masyarakat juga menurun.']],
    [['衡量发展时，必须把可持续性放在重要位置。', 'Héng liáng fā zhǎn shí, bì xū bǎ kě chí xù xìng fàng zài zhòng yào wèi zhì.', 'Saat mengukur pembangunan, keberlanjutan harus ditempatkan pada posisi penting.'], ['低价商品背后往往隐藏着高昂的生态成本。', 'Dī jià shāng pǐn bèi hòu wǎng wǎng yǐn cáng zhe gāo áng de shēng tài chéng běn.', 'Di balik barang murah sering tersembunyi biaya ekologis yang tinggi.'], ['许多城市正在推动交通系统的绿色转型。', 'Xǔ duō chéng shì zhèng zài tuī dòng jiāo tōng xì tǒng de lǜ sè zhuǎn xíng.', 'Banyak kota sedang mendorong transformasi hijau sistem transportasi.']],
    [['合理的舆论引导应该以事实为基础。', 'Hé lǐ de yú lùn yǐn dǎo yīng gāi yǐ shì shí wéi jī chǔ.', 'Pengarahan opini publik yang wajar harus berlandaskan fakta.'], ['普通人借助社交媒体获得了一定的话语权。', 'Pǔ tōng rén jiè zhù shè jiāo méi tǐ huò dé le yí dìng de huà yǔ quán.', 'Orang biasa memperoleh sebagian kuasa wacana melalui media sosial.'], ['学校应该从小培养学生的媒介素养。', 'Xué xiào yīng gāi cóng xiǎo péi yǎng xué shēng de méi jiè sù yǎng.', 'Sekolah sebaiknya menumbuhkan literasi media siswa sejak dini.']],
    [['服务业的就业弹性通常高于制造业。', 'Fú wù yè de jiù yè tán xìng tōng cháng gāo yú zhì zào yè.', 'Elastisitas lapangan kerja sektor jasa biasanya lebih tinggi daripada manufaktur.'], ['重复性强的工作面临更高的替代风险。', 'Chóng fù xìng qiáng de gōng zuò miàn lín gèng gāo de tì dài fēng xiǎn.', 'Pekerjaan yang sangat repetitif menghadapi risiko tergantikan yang lebih tinggi.'], ['政府应当为技能转型提供培训补贴。', 'Zhèng fǔ yīng dāng wèi jì néng zhuǎn xíng tí gōng péi xùn bǔ tiē.', 'Pemerintah sebaiknya menyediakan subsidi pelatihan untuk transformasi keterampilan.']],
    [['在本土语境中，同一个概念可能有不同的含义。', 'Zài běn tǔ yǔ jìng zhōng, tóng yí gè gài niàn kě néng yǒu bù tóng de hán yì.', 'Dalam konteks lokal, satu konsep yang sama bisa bermakna berbeda.'], ['年轻设计师用现代方式实现文化传承。', 'Nián qīng shè jì shī yòng xiàn dài fāng shì shí xiàn wén huà chuán chéng.', 'Para desainer muda mewujudkan pewarisan budaya dengan cara modern.'], ['身份认同的困惑常常出现在移民的第二代身上。', 'Shēn fèn rèn tóng de kùn huò cháng cháng chū xiàn zài yí mín de dì èr dài shēn shàng.', 'Kebingungan identitas sering muncul pada generasi kedua imigran.']],
    [['智慧城市建设正在改变传统的城市治理方式。', 'Zhì huì chéng shì jiàn shè zhèng zài gǎi biàn chuán tǒng de chéng shì zhì lǐ fāng shì.', 'Pembangunan kota pintar sedang mengubah cara tata kelola kota yang tradisional.'], ['公共服务的质量直接影响居民的幸福感。', 'Gōng gòng fú wù de zhì liàng zhí jiē yǐng xiǎng jū mín de xìng fú gǎn.', 'Kualitas layanan publik secara langsung memengaruhi kebahagiaan warga.'], ['基础设施投资应该更多地照顾边缘地区。', 'Jī chǔ shè shī tóu zī yīng gāi gèng duō de zhào gù biān yuán dì qū.', 'Investasi infrastruktur sebaiknya lebih memperhatikan wilayah pinggiran.']],
    [['公共卫生措施需要在效果和成本之间权衡。', 'Gōng gòng wèi shēng cuò shī xū yào zài xiào guǒ hé chéng běn zhī jiān quán héng.', 'Langkah kesehatan masyarakat perlu menimbang antara efektivitas dan biaya.'], ['保护集体利益并不意味着可以忽视个人权利。', 'Bǎo hù jí tǐ lì yì bìng bú yì wèi zhe kě yǐ hū shì gè rén quán lì.', 'Melindungi kepentingan kolektif tidak berarti hak individu boleh diabaikan.'], ['风险沟通的关键是说清楚已知和未知。', 'Fēng xiǎn gōu tōng de guān jiàn shì shuō qīng chu yǐ zhī hé wèi zhī.', 'Kunci komunikasi risiko adalah menjelaskan dengan jelas apa yang sudah dan belum diketahui.']],
    [['过高的试错成本会让年轻人不敢创业。', 'Guò gāo de shì cuò chéng běn huì ràng nián qīng rén bù gǎn chuàng yè.', 'Biaya coba-gagal yang terlalu tinggi membuat anak muda tidak berani berwirausaha.'], ['新兴行业需要灵活的监管框架。', 'Xīn xīng háng yè xū yào líng huó de jiān guǎn kuàng jià.', 'Industri baru membutuhkan kerangka regulasi yang fleksibel.'], ['良好的创新生态离不开大学、企业和资本的合作。', 'Liáng hǎo de chuàng xīn shēng tài lí bù kāi dà xué, qǐ yè hé zī běn de hé zuò.', 'Ekosistem inovasi yang baik tidak lepas dari kerja sama universitas, perusahaan, dan modal.']],
    [['在相互依存的世界里，任何国家都无法独善其身。', 'Zài xiāng hù yī cún de shì jiè lǐ, rèn hé guó jiā dōu wú fǎ dú shàn qí shēn.', 'Di dunia yang saling bergantung, tidak ada negara yang bisa selamat sendirian.'], ['文化适应不是放弃自我，而是学会在新环境中生活。', 'Wén huà shì yìng bú shì fàng qì zì wǒ, ér shì xué huì zài xīn huán jìng zhōng shēng huó.', 'Adaptasi budaya bukan meninggalkan jati diri, melainkan belajar hidup di lingkungan baru.'], ['全球化也激发了人们对地方特色的重视。', 'Quán qiú huà yě jī fā le rén men duì dì fāng tè sè de zhòng shì.', 'Globalisasi juga mendorong orang untuk lebih menghargai kekhasan lokal.']],
    [['打破路径依赖需要勇气和智慧。', 'Dǎ pò lù jìng yī lài xū yào yǒng qì hé zhì huì.', 'Memutus ketergantungan jalur membutuhkan keberanian dan kebijaksanaan.'], ['再好的政策，如果缺乏执行力，也难以落实。', 'Zài hǎo de zhèng cè, rú guǒ quē fá zhí xíng lì, yě nán yǐ luò shí.', 'Kebijakan sebagus apa pun sulit diterapkan jika kurang daya eksekusi.'], ['完善的监督体系是制度改革成功的保障。', 'Wán shàn de jiān dū tǐ xì shì zhì dù gǎi gé chéng gōng de bǎo zhàng.', 'Sistem pengawasan yang lengkap adalah jaminan keberhasilan reformasi kelembagaan.']],
    [['阅读习惯是一种重要的文化资本。', 'Yuè dú xí guàn shì yì zhǒng zhòng yào de wén huà zī běn.', 'Kebiasaan membaca adalah salah satu modal budaya yang penting.'], ['阶层固化会削弱年轻人努力的动力。', 'Jiē céng gù huà huì xuē ruò nián qīng rén nǔ lì de dòng lì.', 'Kemandekan kelas sosial melemahkan dorongan anak muda untuk berusaha.'], ['改善机会结构需要教育、就业和住房政策的配合。', 'Gǎi shàn jī huì jié gòu xū yào jiào yù, jiù yè hé zhù fáng zhèng cè de pèi hé.', 'Memperbaiki struktur kesempatan membutuhkan dukungan kebijakan pendidikan, lapangan kerja, dan perumahan.']],
    [['工厂往往建在低收入社区，这是一个环境正义问题。', 'Gōng chǎng wǎng wǎng jiàn zài dī shōu rù shè qū, zhè shì yí gè huán jìng zhèng yì wèn tí.', 'Pabrik sering dibangun di permukiman berpenghasilan rendah; ini masalah keadilan lingkungan.'], ['污染负担的分配应该公开透明。', 'Wū rǎn fù dān de fēn pèi yīng gāi gōng kāi tòu míng.', 'Pembagian beban pencemaran harus terbuka dan transparan.'], ['生态责任不应只停留在企业的宣传中。', 'Shēng tài zé rèn bù yīng zhǐ tíng liú zài qǐ yè de xuān chuán zhōng.', 'Tanggung jawab ekologis tidak boleh hanya berhenti pada promosi perusahaan.']],
    [['同一个手势在不同文化中可能被误读。', 'Tóng yí gè shǒu shì zài bù tóng wén huà zhōng kě néng bèi wù dú.', 'Isyarat tangan yang sama bisa disalahartikan dalam budaya yang berbeda.'], ['成功的谈判往往从寻找共同利益开始。', 'Chéng gōng de tán pàn wǎng wǎng cóng xún zhǎo gòng tóng lì yì kāi shǐ.', 'Negosiasi yang berhasil sering dimulai dengan mencari kepentingan bersama.'], ['在跨文化沟通中，保持好奇比急于判断更重要。', 'Zài kuà wén huà gōu tōng zhōng, bǎo chí hào qí bǐ jí yú pàn duàn gèng zhòng yào.', 'Dalam komunikasi lintas budaya, menjaga rasa ingin tahu lebih penting daripada terburu-buru menilai.']],
    [['理论框架决定了研究者观察问题的角度。', 'Lǐ lùn kuàng jià jué dìng le yán jiū zhě guān chá wèn tí de jiǎo dù.', 'Kerangka teori menentukan sudut pandang peneliti dalam melihat masalah.'], ['写文献综述时，要指出已有研究的不足。', 'Xiě wén xiàn zōng shù shí, yào zhǐ chū yǐ yǒu yán jiū de bù zú.', 'Saat menulis tinjauan pustaka, kekurangan penelitian yang ada harus ditunjukkan.'], ['清晰的论证链条能让读者跟上作者的思路。', 'Qīng xī de lùn zhèng liàn tiáo néng ràng dú zhě gēn shàng zuò zhě de sī lù.', 'Rantai argumentasi yang jelas membuat pembaca bisa mengikuti alur pikir penulis.']],
    [['批判性阅读不是否定一切，而是有根据地提出疑问。', 'Pī pàn xìng yuè dú bú shì fǒu dìng yí qiè, ér shì yǒu gēn jù de tí chū yí wèn.', 'Membaca kritis bukan menolak segalanya, melainkan mengajukan pertanyaan dengan dasar.'], ['评估证据强度时，要看样本和研究方法。', 'Píng gū zhèng jù qiáng dù shí, yào kàn yàng běn hé yán jiū fāng fǎ.', 'Saat menilai kekuatan bukti, perhatikan sampel dan metode penelitiannya.'], ['指出逻辑漏洞的同时，也应该提出改进建议。', 'Zhǐ chū luó jí lòu dòng de tóng shí, yě yīng gāi tí chū gǎi jìn jiàn yì.', 'Selain menunjukkan celah logika, sebaiknya juga mengajukan saran perbaikan.']],
    [['战略建议必须和组织的长期目标保持一致。', 'Zhàn lüè jiàn yì bì xū hé zǔ zhī de cháng qī mù biāo bǎo chí yí zhì.', 'Rekomendasi strategis harus selaras dengan tujuan jangka panjang organisasi.'], ['忽视关键风险的计划很难经得起考验。', 'Hū shì guān jiàn fēng xiǎn de jì huà hěn nán jīng de qǐ kǎo yàn.', 'Rencana yang mengabaikan risiko kunci sulit bertahan saat diuji.'], ['执行摘要一般不超过一页。', 'Zhí xíng zhāi yào yì bān bù chāo guò yí yè.', 'Ringkasan eksekutif biasanya tidak lebih dari satu halaman.']],
    [['重复关键词是一种常见的修辞策略。', 'Chóng fù guān jiàn cí shì yì zhǒng cháng jiàn de xiū cí cè lüè.', 'Mengulang kata kunci adalah strategi retorika yang umum.'], ['演讲时要清楚地强调焦点，避免信息过多。', 'Yǎn jiǎng shí yào qīng chu de qiáng diào jiāo diǎn, bì miǎn xìn xī guò duō.', 'Saat berpidato, fokus penekanan harus jelas agar informasi tidak berlebihan.'], ['语气控制得好，批评也能让人接受。', 'Yǔ qì kòng zhì de hǎo, pī píng yě néng ràng rén jiē shòu.', 'Jika nada suara terkendali dengan baik, kritik pun bisa diterima.']],
    [['反思日志帮助我发现了自己常犯的错误。', 'Fǎn sī rì zhì bāng zhù wǒ fā xiàn le zì jǐ cháng fàn de cuò wù.', 'Jurnal refleksi membantu saya menemukan kesalahan yang sering saya buat.'], ['成果展示结束后，同学们互相给出了反馈。', 'Chéng guǒ zhǎn shì jié shù hòu, tóng xué men hù xiāng gěi chū le fǎn kuì.', 'Setelah presentasi hasil, teman-teman saling memberi umpan balik.'], ['持续改进的关键在于把反馈变成行动。', 'Chí xù gǎi jìn de guān jiàn zài yú bǎ fǎn kuì biàn chéng xíng dòng.', 'Kunci perbaikan berkelanjutan adalah mengubah umpan balik menjadi tindakan.']],
  ],
  'hsk-7': [
    [['社区参与能让城市更新更符合居民的实际需要。', 'Shè qū cān yù néng ràng chéng shì gēng xīn gèng fú hé jū mín de shí jì xū yào.', 'Partisipasi komunitas membuat pembaruan kota lebih sesuai dengan kebutuhan nyata warga.'], ['这块废弃的空地被改造成了开放的公共空间。', 'Zhè kuài fèi qì de kòng dì bèi gǎi zào chéng le kāi fàng de gōng gòng kōng jiān.', 'Lahan kosong yang terbengkalai ini diubah menjadi ruang publik terbuka.'], ['旧城改造既要改善居住条件，也要留住城市记忆。', 'Jiù chéng gǎi zào jì yào gǎi shàn jū zhù tiáo jiàn, yě yào liú zhù chéng shì jì yì.', 'Renovasi kota lama harus memperbaiki kondisi hunian sekaligus mempertahankan memori kota.']],
    [['普惠金融让更多农民获得了小额贷款。', 'Pǔ huì jīn róng ràng gèng duō nóng mín huò dé le xiǎo é dài kuǎn.', 'Keuangan inklusif membuat lebih banyak petani memperoleh kredit mikro.'], ['为老年人开设手机课程，是缩小数字鸿沟的具体做法。', 'Wèi lǎo nián rén kāi shè shǒu jī kè chéng, shì suō xiǎo shù zì hóng gōu de jù tǐ zuò fǎ.', 'Membuka kursus ponsel bagi lansia adalah cara konkret menyempitkan kesenjangan digital.'], ['信息素养包括判断信息真假的能力。', 'Xìn xī sù yǎng bāo kuò pàn duàn xìn xī zhēn jiǎ de néng lì.', 'Literasi informasi mencakup kemampuan menilai benar-tidaknya informasi.']],
    [['劳动力短缺促使一些企业加快了自动化进程。', 'Láo dòng lì duǎn quē cù shǐ yì xiē qǐ yè jiā kuài le zì dòng huà jìn chéng.', 'Kekurangan tenaga kerja mendorong sebagian perusahaan mempercepat otomatisasi.'], ['延迟退休被视为应对人口老龄化的措施之一。', 'Yán chí tuì xiū bèi shì wéi yìng duì rén kǒu lǎo líng huà de cuò shī zhī yī.', 'Penundaan usia pensiun dipandang sebagai salah satu langkah menghadapi penuaan penduduk.'], ['祖父母帮忙带孩子，是中国代际关系的一个特点。', 'Zǔ fù mǔ bāng máng dài hái zi, shì zhōng guó dài jì guān xì de yí gè tè diǎn.', 'Kakek-nenek membantu mengasuh cucu adalah salah satu ciri hubungan antargenerasi di Tiongkok.']],
    [['素质教育重视学生的创造力和实践能力。', 'Sù zhì jiào yù zhòng shì xué shēng de chuàng zào lì hé shí jiàn néng lì.', 'Pendidikan berbasis kompetensi menekankan kreativitas dan kemampuan praktik siswa.'], ['应试教育使很多学生只为分数而学习。', 'Yìng shì jiào yù shǐ hěn duō xué shēng zhǐ wèi fēn shù ér xué xí.', 'Pendidikan berorientasi ujian membuat banyak siswa belajar hanya demi nilai.'], ['在线课程在一定程度上改善了教育资源分配。', 'Zài xiàn kè chéng zài yí dìng chéng dù shàng gǎi shàn le jiào yù zī yuán fēn pèi.', 'Kursus daring sampai batas tertentu memperbaiki distribusi sumber daya pendidikan.']],
    [['可再生能源的比重逐年提高。', 'Kě zài shēng néng yuán de bǐ zhòng zhú nián tí gāo.', 'Porsi energi terbarukan meningkat dari tahun ke tahun.'], ['极端天气给农业生产带来了巨大损失。', 'Jí duān tiān qì gěi nóng yè shēng chǎn dài lái le jù dà sǔn shī.', 'Cuaca ekstrem menimbulkan kerugian besar bagi produksi pertanian.'], ['企业纷纷制定碳中和的时间表。', 'Qǐ yè fēn fēn zhì dìng tàn zhōng hé de shí jiān biǎo.', 'Perusahaan-perusahaan berlomba menyusun jadwal netralitas karbon.']],
    [['当算法出错时，应该由谁承担责任？这是问责机制要回答的问题。', 'Dāng suàn fǎ chū cuò shí, yīng gāi yóu shuí chéng dān zé rèn? zhè shì wèn zé jī zhì yào huí dá de wèn tí.', 'Saat algoritme keliru, siapa yang harus bertanggung jawab? Itulah pertanyaan yang harus dijawab mekanisme akuntabilitas.'], ['用户有权知道自己的数据被如何使用。', 'Yòng hù yǒu quán zhī dào zì jǐ de shù jù bèi rú hé shǐ yòng.', 'Pengguna berhak mengetahui bagaimana data mereka digunakan.'], ['纠正算法偏见需要多元化的开发团队。', 'Jiū zhèng suàn fǎ piān jiàn xū yào duō yuán huà de kāi fā tuán duì.', 'Memperbaiki bias algoritme membutuhkan tim pengembang yang beragam.']],
    [['社交平台的议程设置能力越来越强。', 'Shè jiāo píng tái de yì chéng shè zhì néng lì yuè lái yuè qiáng.', 'Kemampuan platform sosial dalam menetapkan agenda semakin kuat.'], ['舆论的压力有时能推动问题的解决。', 'Yú lùn de yā lì yǒu shí néng tuī dòng wèn tí de jiě jué.', 'Tekanan opini publik kadang dapat mendorong penyelesaian masalah.'], ['主动阅读不同立场的文章，有助于走出信息茧房。', 'Zhǔ dòng yuè dú bù tóng lì chǎng de wén zhāng, yǒu zhù yú zǒu chū xìn xī jiǎn fáng.', 'Aktif membaca artikel dari sudut pandang berbeda membantu keluar dari gelembung informasi.']],
    [['物质主义容易让人陷入永不满足的比较。', 'Wù zhì zhǔ yì róng yì ràng rén xiàn rù yǒng bù mǎn zú de bǐ jiào.', 'Materialisme mudah membuat orang terjebak dalam perbandingan yang tak pernah puas.'], ['二手交易平台的兴起体现了可持续消费的理念。', 'Èr shǒu jiāo yì píng tái de xīng qǐ tǐ xiàn le kě chí xù xiāo fèi de lǐ niàn.', 'Munculnya platform jual-beli barang bekas mencerminkan gagasan konsumsi berkelanjutan.'], ['在社交媒体的影响下，符号消费越来越普遍。', 'Zài shè jiāo méi tǐ de yǐng xiǎng xià, fú hào xiāo fèi yuè lái yuè pǔ biàn.', 'Di bawah pengaruh media sosial, konsumsi simbolik semakin umum.']],
    [['文化输出不能只靠宣传，更要靠优秀的作品。', 'Wén huà shū chū bù néng zhǐ kào xuān chuán, gèng yào kào yōu xiù de zuò pǐn.', 'Ekspor budaya tidak bisa hanya mengandalkan promosi, tetapi terutama karya yang unggul.'], ['海外华人通过语言和节日维持文化认同。', 'Hǎi wài huá rén tōng guò yǔ yán hé jié rì wéi chí wén huà rèn tóng.', 'Warga Tionghoa perantauan mempertahankan identitas budaya melalui bahasa dan hari raya.'], ['缺乏文化自信的人，往往盲目模仿别人。', 'Quē fá wén huà zì xìn de rén, wǎng wǎng máng mù mó fǎng bié rén.', 'Orang yang kurang percaya diri pada budayanya sering meniru orang lain secara membabi buta.']],
    [['医疗资源集中在大城市，基层医院人手不足。', 'Yī liáo zī yuán jí zhōng zài dà chéng shì, jī céng yī yuàn rén shǒu bù zú.', 'Sumber daya medis terpusat di kota besar, sementara rumah sakit tingkat dasar kekurangan tenaga.'], ['定期体检体现了预防为主的理念。', 'Dìng qī tǐ jiǎn tǐ xiàn le yù fáng wéi zhǔ de lǐ niàn.', 'Pemeriksaan kesehatan berkala mencerminkan prinsip mengutamakan pencegahan.'], ['儿童疫苗接种是公共卫生的重要组成部分。', 'Ér tóng yì miáo jiē zhòng shì gōng gòng wèi shēng de zhòng yào zǔ chéng bù fen.', 'Imunisasi anak adalah bagian penting dari kesehatan masyarakat.']],
    [['农业现代化离不开科技和资金的支持。', 'Nóng yè xiàn dài huà lí bù kāi kē jì hé zī jīn de zhī chí.', 'Modernisasi pertanian tidak lepas dari dukungan teknologi dan modal.'], ['人才回流为乡村带来了新的观念和技术。', 'Rén cái huí liú wèi xiāng cūn dài lái le xīn de guān niàn hé jì shù.', 'Kembalinya talenta membawa gagasan dan teknologi baru ke desa.'], ['城乡差距不仅体现在收入上，也体现在公共服务上。', 'Chéng xiāng chā jù bù jǐn tǐ xiàn zài shōu rù shàng, yě tǐ xiàn zài gōng gòng fú wù shàng.', 'Kesenjangan desa-kota tidak hanya tampak pada pendapatan, tetapi juga pada layanan publik.']],
    [['零工经济给了人们更自由的工作方式。', 'Líng gōng jīng jì gěi le rén men gèng zì yóu de gōng zuò fāng shì.', 'Ekonomi pekerja lepas memberi orang cara bekerja yang lebih bebas.'], ['平台经济的规则应该兼顾效率和公平。', 'Píng tái jīng jì de guī zé yīng gāi jiān gù xiào lǜ hé gōng píng.', 'Aturan ekonomi platform harus memperhatikan efisiensi sekaligus keadilan.'], ['保障骑手的劳动权益已成为社会关注的焦点。', 'Bǎo zhàng qí shǒu de láo dòng quán yì yǐ chéng wéi shè huì guān zhù de jiāo diǎn.', 'Perlindungan hak kerja kurir telah menjadi fokus perhatian masyarakat.']],
    [['越来越多的公司为员工提供心理健康服务。', 'Yuè lái yuè duō de gōng sī wèi yuán gōng tí gōng xīn lǐ jiàn kāng fú wù.', 'Semakin banyak perusahaan menyediakan layanan kesehatan jiwa bagi karyawan.'], ['消除污名化，才能让患者勇敢地寻求帮助。', 'Xiāo chú wū míng huà, cái néng ràng huàn zhě yǒng gǎn de xún qiú bāng zhù.', 'Hanya dengan menghapus stigma, pasien berani mencari bantuan.'], ['考试前的焦虑是很常见的情绪。', 'Kǎo shì qián de jiāo lǜ shì hěn cháng jiàn de qíng xù.', 'Kecemasan sebelum ujian adalah emosi yang sangat umum.']],
    [['许多实验室的成果转化率仍然偏低。', 'Xǔ duō shí yàn shì de chéng guǒ zhuǎn huà lǜ réng rán piān dī.', 'Tingkat hilirisasi hasil riset di banyak laboratorium masih rendah.'], ['侵犯知识产权会打击创新者的积极性。', 'Qīn fàn zhī shi chǎn quán huì dǎ jī chuàng xīn zhě de jī jí xìng.', 'Pelanggaran hak kekayaan intelektual melemahkan semangat para inovator.'], ['研发投入的多少是衡量企业创新能力的重要指标。', 'Yán fā tóu rù de duō shǎo shì héng liáng qǐ yè chuàng xīn néng lì de zhòng yào zhǐ biāo.', 'Besarnya investasi litbang adalah indikator penting kemampuan inovasi perusahaan.']],
    [['一种语言如果没有年轻人使用，就会失去语言活力。', 'Yì zhǒng yǔ yán rú guǒ méi yǒu nián qīng rén shǐ yòng, jiù huì shī qù yǔ yán huó lì.', 'Jika suatu bahasa tidak dipakai anak muda, bahasa itu akan kehilangan vitalitasnya.'], ['方言保护可以通过录音和教学两种方式进行。', 'Fāng yán bǎo hù kě yǐ tōng guò lù yīn hé jiào xué liǎng zhǒng fāng shì jìn xíng.', 'Pelestarian dialek bisa dilakukan melalui perekaman dan pengajaran.'], ['双语教育要求教师具备良好的语言能力。', 'Shuāng yǔ jiào yù yāo qiú jiào shī jù bèi liáng hǎo de yǔ yán néng lì.', 'Pendidikan dwibahasa menuntut guru memiliki kemampuan bahasa yang baik.']],
    [['灵活就业人员的社会保障需要进一步完善。', 'Líng huó jiù yè rén yuán de shè huì bǎo zhàng xū yào jìn yí bù wán shàn.', 'Jaminan sosial bagi pekerja fleksibel perlu disempurnakan lebih lanjut.'], ['高校课程应该根据产业升级及时调整。', 'Gāo xiào kè chéng yīng gāi gēn jù chǎn yè shēng jí jí shí tiáo zhěng.', 'Kurikulum perguruan tinggi harus disesuaikan tepat waktu dengan peningkatan industri.'], ['解决技能错配需要企业和学校的深度合作。', 'Jiě jué jì néng cuò pèi xū yào qǐ yè hé xué xiào de shēn dù hé zuò.', 'Mengatasi ketidaksesuaian keterampilan membutuhkan kerja sama erat antara perusahaan dan sekolah.']],
    [['剪纸艺术是一项珍贵的非物质文化遗产。', 'Jiǎn zhǐ yì shù shì yí xiàng zhēn guì de fēi wù zhì wén huà yí chǎn.', 'Seni potong kertas adalah warisan budaya takbenda yang berharga.'], ['保护文化遗产需要在利用和保存之间找到平衡。', 'Bǎo hù wén huà yí chǎn xū yào zài lì yòng hé bǎo cún zhī jiān zhǎo dào píng héng.', 'Melindungi warisan budaya perlu menemukan keseimbangan antara pemanfaatan dan pelestarian.'], ['活态传承离不开年轻一代的参与。', 'Huó tài chuán chéng lí bù kāi nián qīng yí dài de cān yù.', 'Pewarisan yang hidup tidak lepas dari partisipasi generasi muda.']],
    [['遵守引用规范是尊重他人劳动的表现。', 'Zūn shǒu yǐn yòng guī fàn shì zūn zhòng tā rén láo dòng de biǎo xiàn.', 'Mematuhi aturan kutipan adalah wujud menghargai kerja orang lain.'], ['同行评审能够发现作者自己没有注意到的问题。', 'Tóng háng píng shěn néng gòu fā xiàn zuò zhě zì jǐ méi yǒu zhù yì dào de wèn tí.', 'Telaah sejawat dapat menemukan masalah yang tidak disadari penulis sendiri.'], ['许多大学使用软件检测论文是否抄袭。', 'Xǔ duō dà xué shǐ yòng ruǎn jiàn jiǎn cè lùn wén shì fǒu chāo xí.', 'Banyak universitas memakai perangkat lunak untuk mendeteksi plagiarisme.']],
    [['共同利益是国家之间合作的基础。', 'Gòng tóng lì yì shì guó jiā zhī jiān hé zuò de jī chǔ.', 'Kepentingan bersama adalah dasar kerja sama antarnegara.'], ['在气候问题上，国际合作显得尤为迫切。', 'Zài qì hòu wèn tí shàng, guó jì hé zuò xiǎn de yóu wéi pò qiè.', 'Dalam isu iklim, kerja sama internasional terasa sangat mendesak.'], ['缺乏互信，再好的协议也难以执行。', 'Quē fá hù xìn, zài hǎo de xié yì yě nán yǐ zhí xíng.', 'Tanpa saling percaya, perjanjian sebaik apa pun sulit dilaksanakan.']],
    [['学术报告结束后，听众提出了几个尖锐的问题。', 'Xué shù bào gào jié shù hòu, tīng zhòng tí chū le jǐ gè jiān ruì de wèn tí.', 'Setelah laporan akademik, hadirin mengajukan beberapa pertanyaan tajam.'], ['准备答辩时，要预先想好评委可能提出的问题。', 'Zhǔn bèi dá biàn shí, yào yù xiān xiǎng hǎo píng wěi kě néng tí chū de wèn tí.', 'Saat menyiapkan sidang, pikirkan lebih dulu pertanyaan yang mungkin diajukan penguji.'], ['综合评述要求把不同研究的结论放在一起比较。', 'Zōng hé píng shù yāo qiú bǎ bù tóng yán jiū de jié lùn fàng zài yì qǐ bǐ jiào.', 'Tinjauan komprehensif menuntut kesimpulan berbagai penelitian dibandingkan bersama.']],
  ],
  'hsk-8': [
    [['税收优惠是一种常见的政策工具。', 'Shuì shōu yōu huì shì yì zhǒng cháng jiàn de zhèng cè gōng jù.', 'Insentif pajak adalah instrumen kebijakan yang umum.'], ['产业政策应该有明确的退出机制。', 'Chǎn yè zhèng cè yīng gāi yǒu míng què de tuì chū jī zhì.', 'Kebijakan industri seharusnya memiliki mekanisme keluar yang jelas.'], ['补贴如果分配不当，会造成资源浪费。', 'Bǔ tiē rú guǒ fēn pèi bù dàng, huì zào chéng zī yuán làng fèi.', 'Jika subsidi dibagikan dengan tidak tepat, akan terjadi pemborosan sumber daya.']],
    [['地方政府的债务风险需要严格控制。', 'Dì fāng zhèng fǔ de zhài wù fēng xiǎn xū yào yán gé kòng zhì.', 'Risiko utang pemerintah daerah perlu dikendalikan dengan ketat.'], ['税收结构不合理会加重中低收入者的负担。', 'Shuì shōu jié gòu bù hé lǐ huì jiā zhòng zhōng dī shōu rù zhě de fù dān.', 'Struktur pajak yang tidak wajar memperberat beban kelompok berpendapatan menengah ke bawah.'], ['经济下行时，适度扩大财政赤字可以刺激需求。', 'Jīng jì xià xíng shí, shì dù kuò dà cái zhèng chì zì kě yǐ cì jī xū qiú.', 'Saat ekonomi melambat, memperlebar defisit fiskal secara moderat dapat merangsang permintaan.']],
    [['社会保障制度是维护社会稳定的安全网。', 'Shè huì bǎo zhàng zhì dù shì wéi hù shè huì wěn dìng de ān quán wǎng.', 'Sistem jaminan sosial adalah jaring pengaman untuk menjaga stabilitas sosial.'], ['农村地区的医疗保险覆盖面已经大大扩大。', 'Nóng cūn dì qū de yī liáo bǎo xiǎn fù gài miàn yǐ jīng dà dà kuò dà.', 'Cakupan asuransi kesehatan di pedesaan sudah sangat meluas.'], ['最低生活保障属于兜底保障的范围。', 'Zuì dī shēng huó bǎo zhàng shǔ yú dōu dǐ bǎo zhàng de fàn wéi.', 'Tunjangan hidup minimum termasuk dalam lingkup jaminan dasar terakhir.']],
    [['城镇化的核心是人的城镇化，而不仅是土地的城镇化。', 'Chéng zhèn huà de hé xīn shì rén de chéng zhèn huà, ér bù jǐn shì tǔ dì de chéng zhèn huà.', 'Inti urbanisasi adalah urbanisasi manusia, bukan hanya urbanisasi lahan.'], ['公共服务均等化意味着无论户籍在哪里，都能享受基本服务。', 'Gōng gòng fú wù jūn děng huà yì wèi zhe wú lùn hù jí zài nǎ lǐ, dōu néng xiǎng shòu jī běn fú wù.', 'Pemerataan layanan publik berarti layanan dasar dapat dinikmati di mana pun domisili terdaftar.'], ['一些城市放宽了户籍制度，吸引年轻人落户。', 'Yì xiē chéng shì fàng kuān le hù jí zhì dù, xī yǐn nián qīng rén luò hù.', 'Sebagian kota melonggarkan sistem registrasi penduduk untuk menarik anak muda menetap.']],
    [['电网的稳定运行是能源转型的前提。', 'Diàn wǎng de wěn dìng yùn xíng shì néng yuán zhuǎn xíng de qián tí.', 'Operasi jaringan listrik yang stabil adalah prasyarat transisi energi.'], ['大规模储能可以解决风电和光伏发电不稳定的问题。', 'Dà guī mó chǔ néng kě yǐ jiě jué fēng diàn hé guāng fú fā diàn bù wěn dìng de wèn tí.', 'Penyimpanan energi skala besar dapat mengatasi ketidakstabilan pembangkit angin dan surya.'], ['随着技术进步，电池的成本曲线还会继续下降。', 'Suí zhe jì shù jìn bù, diàn chí de chéng běn qū xiàn hái huì jì xù xià jiàng.', 'Seiring kemajuan teknologi, kurva biaya baterai akan terus menurun.']],
    [['合规已经成为科技企业的核心竞争力之一。', 'Hé guī yǐ jīng chéng wéi kē jì qǐ yè de hé xīn jìng zhēng lì zhī yī.', 'Kepatuhan telah menjadi salah satu daya saing inti perusahaan teknologi.'], ['数据的跨境流动涉及国家安全和个人隐私。', 'Shù jù de kuà jìng liú dòng shè jí guó jiā ān quán hé gè rén yǐn sī.', 'Aliran data lintas batas menyangkut keamanan negara dan privasi individu.'], ['没有清晰的数据确权，数据交易就难以开展。', 'Méi yǒu qīng xī de shù jù què quán, shù jù jiāo yì jiù nán yǐ kāi zhǎn.', 'Tanpa kepastian kepemilikan data, perdagangan data sulit dijalankan.']],
    [['同行评议应当尽量避免利益冲突。', 'Tóng háng píng yì yīng dāng jǐn liàng bì miǎn lì yì chōng tū.', 'Penelaahan sejawat sebaiknya menghindari konflik kepentingan.'], ['影响因子高的期刊并不代表每篇论文都优秀。', 'Yǐng xiǎng yīn zǐ gāo de qī kān bìng bú dài biǎo měi piān lùn wén dōu yōu xiù.', 'Jurnal berfaktor dampak tinggi tidak berarti setiap artikelnya unggul.'], ['改革科研评价，需要把社会贡献纳入考核。', 'Gǎi gé kē yán píng jià, xū yào bǎ shè huì gòng xiàn nà rù kǎo hé.', 'Mereformasi evaluasi riset perlu memasukkan kontribusi sosial ke dalam penilaian.']],
    [['一座有韧性的城市能够在灾害后迅速恢复。', 'Yí zuò yǒu rèn xìng de chéng shì néng gòu zài zāi hài hòu xùn sù huī fù.', 'Kota yang tangguh dapat pulih dengan cepat setelah bencana.'], ['应急管理不仅包括救援，还包括预警和恢复。', 'Yìng jí guǎn lǐ bù jǐn bāo kuò jiù yuán, hái bāo kuò yù jǐng hé huī fù.', 'Manajemen kedaruratan tidak hanya mencakup penyelamatan, tetapi juga peringatan dini dan pemulihan.'], ['在风险沟通中，前后矛盾的信息最容易损害公信力。', 'Zài fēng xiǎn gōu tōng zhōng, qián hòu máo dùn de xìn xī zuì róng yì sǔn hài gōng xìn lì.', 'Dalam komunikasi risiko, informasi yang saling bertentangan paling mudah merusak kredibilitas.']],
    [['增值评价关注学生在原有基础上的进步程度。', 'Zēng zhí píng jià guān zhù xué shēng zài yuán yǒu jī chǔ shàng de jìn bù chéng dù.', 'Evaluasi nilai tambah memperhatikan tingkat kemajuan siswa dari kemampuan awalnya.'], ['减负政策实施以后，学生的课外时间增加了。', 'Jiǎn fù zhèng cè shí shī yǐ hòu, xué shēng de kè wài shí jiān zēng jiā le.', 'Setelah kebijakan pengurangan beban dijalankan, waktu luar kelas siswa bertambah.'], ['单一的评价体系难以反映学生的多方面能力。', 'Dān yī de píng jià tǐ xì nán yǐ fǎn yìng xué shēng de duō fāng miàn néng lì.', 'Sistem evaluasi tunggal sulit mencerminkan beragam kemampuan siswa.']],
    [['投资人力资本是提高劳动生产率的根本途径。', 'Tóu zī rén lì zī běn shì tí gāo láo dòng shēng chǎn lǜ de gēn běn tú jìng.', 'Berinvestasi pada modal manusia adalah jalan mendasar meningkatkan produktivitas tenaga kerja.'], ['最低工资标准应该根据物价水平定期调整。', 'Zuì dī gōng zī biāo zhǔn yīng gāi gēn jù wù jià shuǐ píng dìng qī tiáo zhěng.', 'Standar upah minimum sebaiknya disesuaikan berkala sesuai tingkat harga.'], ['应对结构性失业，关键在于职业培训。', 'Yìng duì jié gòu xìng shī yè, guān jiàn zài yú zhí yè péi xùn.', 'Kunci menghadapi pengangguran struktural terletak pada pelatihan kerja.']],
    [['降低企业的杠杆率有助于防范债务危机。', 'Jiàng dī qǐ yè de gàng gǎn lǜ yǒu zhù yú fáng fàn zhài wù wēi jī.', 'Menurunkan rasio leverage perusahaan membantu mencegah krisis utang.'], ['宏观审慎管理弥补了单个机构监管的不足。', 'Hóng guān shěn shèn guǎn lǐ mí bǔ le dān gè jī gòu jiān guǎn de bù zú.', 'Manajemen makroprudensial menutupi kekurangan pengawasan per lembaga.'], ['新型金融产品给金融监管带来了新挑战。', 'Xīn xíng jīn róng chǎn pǐn gěi jīn róng jiān guǎn dài lái le xīn tiǎo zhàn.', 'Produk keuangan jenis baru membawa tantangan baru bagi regulasi keuangan.']],
    [['碳交易让排放权成为可以买卖的商品。', 'Tàn jiāo yì ràng pái fàng quán chéng wéi kě yǐ mǎi mài de shāng pǐn.', 'Perdagangan karbon menjadikan hak emisi sebagai komoditas yang dapat diperjualbelikan.'], ['如果执法力度不够，环境法律就会成为一纸空文。', 'Rú guǒ zhí fǎ lì dù bú gòu, huán jìng fǎ lǜ jiù huì chéng wéi yì zhǐ kōng wén.', 'Jika penegakan hukum lemah, undang-undang lingkungan hanya menjadi tulisan di atas kertas.'], ['严格的环境规制也可能倒逼企业技术创新。', 'Yán gé de huán jìng guī zhì yě kě néng dào bī qǐ yè jì shù chuàng xīn.', 'Regulasi lingkungan yang ketat juga dapat memaksa perusahaan berinovasi teknologi.']],
    [['平台利用市场支配地位强迫商家二选一，属于违法行为。', 'Píng tái lì yòng shì chǎng zhī pèi dì wèi qiǎng pò shāng jiā èr xuǎn yī, shǔ yú wéi fǎ xíng wéi.', 'Platform yang memakai posisi dominannya untuk memaksa pedagang memilih salah satu melakukan pelanggaran hukum.'], ['网络效应越强，新企业进入市场就越困难。', 'Wǎng luò xiào yìng yuè qiáng, xīn qǐ yè jìn rù shì chǎng jiù yuè kùn nán.', 'Semakin kuat efek jaringan, semakin sulit perusahaan baru masuk pasar.'], ['监管机构正在研究如何识别算法合谋。', 'Jiān guǎn jī gòu zhèng zài yán jiū rú hé shí bié suàn fǎ hé móu.', 'Regulator sedang mengkaji cara mengenali kolusi algoritme.']],
    [['延长产假是提高生育率的政策之一。', 'Yán cháng chǎn jià shì tí gāo shēng yù lǜ de zhèng cè zhī yī.', 'Memperpanjang cuti melahirkan adalah salah satu kebijakan untuk meningkatkan angka kelahiran.'], ['人口红利消失后，经济增长需要依靠创新。', 'Rén kǒu hóng lì xiāo shī hòu, jīng jì zēng zhǎng xū yào yī kào chuàng xīn.', 'Setelah bonus demografi berakhir, pertumbuhan ekonomi harus bertumpu pada inovasi.'], ['政策效果评估显示，单纯的现金补贴作用有限。', 'Zhèng cè xiào guǒ píng gū xiǎn shì, dān chún de xiàn jīn bǔ tiē zuò yòng yǒu xiàn.', 'Evaluasi dampak kebijakan menunjukkan subsidi tunai semata efeknya terbatas.']],
    [['高铁网络加快了人才和资本等要素流动。', 'Gāo tiě wǎng luò jiā kuài le rén cái hé zī běn děng yào sù liú dòng.', 'Jaringan kereta cepat mempercepat aliran faktor produksi seperti talenta dan modal.'], ['产业转移需要考虑当地的环境承载力。', 'Chǎn yè zhuǎn yí xū yào kǎo lǜ dāng dì de huán jìng chéng zài lì.', 'Relokasi industri perlu mempertimbangkan daya dukung lingkungan setempat.'], ['实现区域协调发展，需要建立利益共享机制。', 'Shí xiàn qū yù xié tiáo fā zhǎn, xū yào jiàn lì lì yì gòng xiǎng jī zhì.', 'Mewujudkan pembangunan regional yang terkoordinasi membutuhkan mekanisme berbagi manfaat.']],
    [['数字化转型让古籍资源可以在线阅读。', 'Shù zì huà zhuǎn xíng ràng gǔ jí zī yuán kě yǐ zài xiàn yuè dú.', 'Transformasi digital membuat kitab kuno dapat dibaca secara daring.'], ['文化供给应该更好地回应居民的真实需求。', 'Wén huà gōng jǐ yīng gāi gèng hǎo de huí yìng jū mín de zhēn shí xū qiú.', 'Penyediaan layanan budaya sebaiknya lebih menjawab kebutuhan nyata warga.'], ['社区举办的读书会提高了居民的参与度。', 'Shè qū jǔ bàn de dú shū huì tí gāo le jū mín de cān yù dù.', 'Klub buku yang diadakan komunitas meningkatkan tingkat partisipasi warga.']],
    [['新的贸易规则越来越重视数字贸易和环境标准。', 'Xīn de mào yì guī zé yuè lái yuè zhòng shì shù zì mào yì hé huán jìng biāo zhǔn.', 'Aturan perdagangan baru semakin menekankan perdagangan digital dan standar lingkungan.'], ['企业通过多元化采购来提高供应链韧性。', 'Qǐ yè tōng guò duō yuán huà cǎi gòu lái tí gāo gōng yìng liàn rèn xìng.', 'Perusahaan meningkatkan ketahanan rantai pasok melalui diversifikasi pengadaan.'], ['复杂的原产地规则增加了企业的合规成本。', 'Fù zá de yuán chǎn dì guī zé zēng jiā le qǐ yè de hé guī chéng běn.', 'Aturan asal barang yang rumit menambah biaya kepatuhan perusahaan.']],
    [['只调查网上用户，可能导致样本偏差。', 'Zhǐ diào chá wǎng shàng yòng hù, kě néng dǎo zhì yàng běn piān chā.', 'Hanya menyurvei pengguna daring dapat menyebabkan bias sampel.'], ['随机对照实验是因果推断的重要方法。', 'Suí jī duì zhào shí yàn shì yīn guǒ tuī duàn de zhòng yào fāng fǎ.', 'Uji terkontrol acak adalah metode penting inferensi kausal.'], ['审稿人要求作者补充稳健性检验。', 'Shěn gǎo rén yāo qiú zuò zhě bǔ chōng wěn jiàn xìng jiǎn yàn.', 'Penelaah meminta penulis menambahkan uji ketahanan hasil.']],
    [['构建反事实情景是评估政策效果的核心难题。', 'Gòu jiàn fǎn shì shí qíng jǐng shì píng gū zhèng cè xiào guǒ de hé xīn nán tí.', 'Membangun skenario kontrafaktual adalah kesulitan inti dalam menilai dampak kebijakan.'], ['指标体系的设计应该兼顾全面性和可操作性。', 'Zhǐ biāo tǐ xì de shè jì yīng gāi jiān gù quán miàn xìng hé kě cāo zuò xìng.', 'Rancangan sistem indikator harus mempertimbangkan kelengkapan sekaligus keterlaksanaan.'], ['政策评估的结果应该向社会公开。', 'Zhèng cè píng gū de jié guǒ yīng gāi xiàng shè huì gōng kāi.', 'Hasil evaluasi kebijakan sebaiknya dibuka kepada publik.']],
    [['只有结论稳健，政策建议才有说服力。', 'Zhǐ yǒu jié lùn wěn jiàn, zhèng cè jiàn yì cái yǒu shuō fú lì.', 'Hanya jika kesimpulannya kokoh, rekomendasi kebijakan menjadi meyakinkan.'], ['这份政策建议书提出了三条具体措施。', 'Zhè fèn zhèng cè jiàn yì shū tí chū le sān tiáo jù tǐ cuò shī.', 'Naskah rekomendasi kebijakan ini mengajukan tiga langkah konkret.'], ['好的研究综述能帮助读者快速了解一个领域。', 'Hǎo de yán jiū zōng shù néng bāng zhù dú zhě kuài sù liǎo jiě yí gè lǐng yù.', 'Tinjauan riset yang baik membantu pembaca cepat memahami suatu bidang.']],
  ],
  'hsk-9': [
    [['在高度分工的工厂里，工人容易感到异化。', 'Zài gāo dù fēn gōng de gōng chǎng lǐ, gōng rén róng yì gǎn dào yì huà.', 'Di pabrik dengan pembagian kerja yang tinggi, pekerja mudah merasa teralienasi.'], ['理性化使社会运转更加高效，却也使生活更加刻板。', 'Lǐ xìng huà shǐ shè huì yùn zhuǎn gèng jiā gāo xiào, què yě shǐ shēng huó gèng jiā kè bǎn.', 'Rasionalisasi membuat masyarakat berjalan lebih efisien, tetapi juga membuat hidup lebih kaku.'], ['反思现代性，并不是要回到过去。', 'Fǎn sī xiàn dài xìng, bìng bú shì yào huí dào guò qù.', 'Merefleksikan modernitas bukan berarti kembali ke masa lalu.']],
    [['专家的权威来自知识，也来自社会的认可。', 'Zhuān jiā de quán wēi lái zì zhī shi, yě lái zì shè huì de rèn kě.', 'Otoritas pakar berasal dari pengetahuan dan juga dari pengakuan masyarakat.'], ['不同的认识论立场决定了不同的研究方法。', 'Bù tóng de rèn shi lùn lì chǎng jué dìng le bù tóng de yán jiū fāng fǎ.', 'Posisi epistemologis yang berbeda menentukan metode penelitian yang berbeda.'], ['教科书的编写本身就是一种知识建构。', 'Jiào kē shū de biān xiě běn shēn jiù shì yì zhǒng zhī shi jiàn gòu.', 'Penyusunan buku pelajaran itu sendiri adalah suatu konstruksi pengetahuan.']],
    [['后人类思想追问人与机器的界限究竟在哪里。', 'Hòu rén lèi sī xiǎng zhuī wèn rén yǔ jī qì de jiè xiàn jiū jìng zài nǎ lǐ.', 'Pemikiran pascamanusia mempertanyakan di mana sebenarnya batas antara manusia dan mesin.'], ['在算法面前，个体的主体性正在受到挑战。', 'Zài suàn fǎ miàn qián, gè tǐ de zhǔ tǐ xìng zhèng zài shòu dào tiǎo zhàn.', 'Di hadapan algoritme, subjektivitas individu sedang ditantang.'], ['过度强调工具理性，会让人忽视行为的意义。', 'Guò dù qiáng diào gōng jù lǐ xìng, huì ràng rén hū shì xíng wéi de yì yì.', 'Terlalu menekankan rasionalitas instrumental membuat orang mengabaikan makna tindakan.']],
    [['价值多元并不意味着一切观点都同样合理。', 'Jià zhí duō yuán bìng bú yì wèi zhe yí qiè guān diǎn dōu tóng yàng hé lǐ.', 'Pluralitas nilai tidak berarti semua pandangan sama masuk akalnya.'], ['共识不是消除分歧，而是在分歧中找到可接受的方案。', 'Gòng shí bú shì xiāo chú fēn qí, ér shì zài fēn qí zhōng zhǎo dào kě jiē shòu de fāng àn.', 'Konsensus bukan menghapus perbedaan, melainkan menemukan solusi yang dapat diterima di tengah perbedaan.'], ['社区议事会是协商民主的一种实践形式。', 'Shè qū yì shì huì shì xié shāng mín zhǔ de yì zhǒng shí jiàn xíng shì.', 'Musyawarah warga adalah salah satu bentuk praktik demokrasi deliberatif.']],
    [['理解他者，首先要放下自己的成见。', 'Lǐ jiě tā zhě, shǒu xiān yào fàng xià zì jǐ de chéng jiàn.', 'Memahami liyan dimulai dengan melepaskan prasangka sendiri.'], ['丝绸之路是古代文明互鉴的生动例证。', 'Sī chóu zhī lù shì gǔ dài wén míng hù jiàn de shēng dòng lì zhèng.', 'Jalur Sutra adalah contoh nyata saling belajar antarperadaban di masa lalu.'], ['人权的普遍性与文化的特殊性之间存在张力。', 'Rén quán de pǔ biàn xìng yǔ wén huà de tè shū xìng zhī jiān cún zài zhāng lì.', 'Ada ketegangan antara universalitas hak asasi dan kekhususan budaya.']],
    [['保护物种多样性体现了超越人类中心主义的生态伦理。', 'Bǎo hù wù zhǒng duō yàng xìng tǐ xiàn le chāo yuè rén lèi zhōng xīn zhǔ yì de shēng tài lún lǐ.', 'Melindungi keanekaragaman spesies mencerminkan etika ekologis yang melampaui antroposentrisme.'], ['可持续性要求当代人的发展不损害后代的需要。', 'Kě chí xù xìng yāo qiú dāng dài rén de fā zhǎn bù sǔn hài hòu dài de xū yào.', 'Keberlanjutan menuntut pembangunan generasi kini tidak merugikan kebutuhan generasi mendatang.'], ['代际正义让我们思考对尚未出生的人负有什么责任。', 'Dài jì zhèng yì ràng wǒ men sī kǎo duì shàng wèi chū shēng de rén fù yǒu shén me zé rèn.', 'Keadilan antargenerasi mengajak kita memikirkan tanggung jawab terhadap mereka yang belum lahir.']],
    [['博物馆的展览方式影响着公众的集体记忆。', 'Bó wù guǎn de zhǎn lǎn fāng shì yǐng xiǎng zhe gōng zhòng de jí tǐ jì yì.', 'Cara pameran museum memengaruhi memori kolektif publik.'], ['个人的回忆录也可以成为历史书写的重要补充。', 'Gè rén de huí yì lù yě kě yǐ chéng wéi lì shǐ shū xiě de zhòng yào bǔ chōng.', 'Memoar pribadi juga dapat menjadi pelengkap penting penulisan sejarah.'], ['移民通过讲述家族故事来重建身份认同。', 'Yí mín tōng guò jiǎng shù jiā zú gù shì lái chóng jiàn shēn fèn rèn tóng.', 'Para imigran membangun kembali identitas dengan menceritakan kisah keluarga.']],
    [['通过话语分析，我们可以看到新闻中隐藏的立场。', 'Tōng guò huà yǔ fēn xī, wǒ men kě yǐ kàn dào xīn wén zhōng yǐn cáng de lì chǎng.', 'Melalui analisis wacana, kita dapat melihat sikap yang tersembunyi dalam berita.'], ['任何语言都不可能完全脱离意识形态。', 'Rèn hé yǔ yán dōu bù kě néng wán quán tuō lí yì shí xíng tài.', 'Tidak ada bahasa yang bisa sepenuhnya lepas dari ideologi.'], ['解构主义提醒我们注意文本中被压抑的声音。', 'Jiě gòu zhǔ yì tí xǐng wǒ men zhù yì wén běn zhōng bèi yā yì de shēng yīn.', 'Dekonstruksi mengingatkan kita untuk memperhatikan suara yang ditekan dalam teks.']],
    [['很多古典诗词与前代作品之间存在互文性。', 'Hěn duō gǔ diǎn shī cí yǔ qián dài zuò pǐn zhī jiān cún zài hù wén xìng.', 'Banyak puisi klasik memiliki intertekstualitas dengan karya-karya sebelumnya.'], ['不同的阐释反映了读者所处时代的关注。', 'Bù tóng de chǎn shì fǎn yìng le dú zhě suǒ chǔ shí dài de guān zhù.', 'Tafsiran yang berbeda mencerminkan perhatian zaman pembacanya.'], ['把经典语境化，可以避免用今天的标准简单评判古人。', 'Bǎ jīng diǎn yǔ jìng huà, kě yǐ bì miǎn yòng jīn tiān de biāo zhǔn jiǎn dān píng pàn gǔ rén.', 'Mengontekstualisasikan karya klasik menghindarkan kita dari menilai orang zaman dulu semata dengan standar masa kini.']],
    [['气候系统中存在许多相互作用的反馈回路。', 'Qì hòu xì tǒng zhōng cún zài xǔ duō xiāng hù zuò yòng de fǎn kuì huí lù.', 'Dalam sistem iklim terdapat banyak lingkaran umpan balik yang saling berinteraksi.'], ['城市交通是一个典型的复杂系统。', 'Chéng shì jiāo tōng shì yí gè diǎn xíng de fù zá xì tǒng.', 'Lalu lintas kota adalah contoh khas sistem kompleks.'], ['市场中的恐慌情绪会以非线性的方式迅速放大。', 'Shì chǎng zhōng de kǒng huāng qíng xù huì yǐ fēi xiàn xìng de fāng shì xùn sù fàng dà.', 'Kepanikan di pasar dapat membesar dengan cepat secara nonlinier.']],
    [['在风险社会中，风险往往是现代化本身的产物。', 'Zài fēng xiǎn shè huì zhōng, fēng xiǎn wǎng wǎng shì xiàn dài huà běn shēn de chǎn wù.', 'Dalam masyarakat risiko, risiko sering merupakan produk modernisasi itu sendiri.'], ['我们乘坐飞机，就是在信任一整套专家系统。', 'Wǒ men chéng zuò fēi jī, jiù shì zài xìn rèn yì zhěng tào zhuān jiā xì tǒng.', 'Saat naik pesawat, kita sedang memercayai seluruh sistem keahlian.'], ['面对高度的不确定性，政策需要保留调整的空间。', 'Miàn duì gāo dù de bú què dìng xìng, zhèng cè xū yào bǎo liú tiáo zhěng de kōng jiān.', 'Menghadapi ketidakpastian yang tinggi, kebijakan perlu menyisakan ruang penyesuaian.']],
    [['国际组织的规则体现了各国的制度性话语权。', 'Guó jì zǔ zhī de guī zé tǐ xiàn le gè guó de zhì dù xìng huà yǔ quán.', 'Aturan organisasi internasional mencerminkan kuasa wacana kelembagaan tiap negara.'], ['网络空间的全球治理仍在探索之中。', 'Wǎng luò kōng jiān de quán qiú zhì lǐ réng zài tàn suǒ zhī zhōng.', 'Tata kelola global ruang siber masih dalam tahap penjajakan.'], ['主权国家在全球问题面前既是参与者，也是限制因素。', 'Zhǔ quán guó jiā zài quán qiú wèn tí miàn qián jì shì cān yù zhě, yě shì xiàn zhì yīn sù.', 'Dalam isu global, negara berdaulat adalah peserta sekaligus faktor pembatas.']],
    [['审美判断既有个人差异，也有共通之处。', 'Shěn měi pàn duàn jì yǒu gè rén chā yì, yě yǒu gòng tōng zhī chù.', 'Penilaian estetis memiliki perbedaan pribadi sekaligus kesamaan.'], ['山水画的留白为观者创造了想象的意境。', 'Shān shuǐ huà de liú bái wèi guān zhě chuàng zào le xiǎng xiàng de yì jìng.', 'Ruang kosong dalam lukisan pemandangan menciptakan suasana imajinatif bagi penikmatnya.'], ['形式与内容脱节的作品很难打动人心。', 'Xíng shì yǔ nèi róng tuō jié de zuò pǐn hěn nán dǎ dòng rén xīn.', 'Karya yang bentuk dan isinya tidak menyatu sulit menyentuh hati.']],
    [['归纳法无法保证结论的绝对正确。', 'Guī nà fǎ wú fǎ bǎo zhèng jié lùn de jué duì zhèng què.', 'Metode induksi tidak dapat menjamin kebenaran mutlak kesimpulan.'], ['一个理论如果不具有可证伪性，就难以被检验。', 'Yí gè lǐ lùn rú guǒ bú jù yǒu kě zhèng wěi xìng, jiù nán yǐ bèi jiǎn yàn.', 'Jika suatu teori tidak dapat difalsifikasi, teori itu sulit diuji.'], ['新的范式往往首先被年轻学者接受。', 'Xīn de fàn shì wǎng wǎng shǒu xiān bèi nián qīng xué zhě jiē shòu.', 'Paradigma baru sering pertama kali diterima oleh akademisi muda.']],
    [['什么是一个人应得的，往往是争论的焦点。', 'Shén me shì yí gè rén yīng dé de, wǎng wǎng shì zhēng lùn de jiāo diǎn.', 'Apa yang layak diterima seseorang sering menjadi pokok perdebatan.'], ['税收和转移支付是实现分配正义的重要手段。', 'Shuì shōu hé zhuǎn yí zhī fù shì shí xiàn fēn pèi zhèng yì de zhòng yào shǒu duàn.', 'Pajak dan transfer fiskal adalah sarana penting mewujudkan keadilan distributif.'], ['如果程序不公开，结果再公平也难以令人信服。', 'Rú guǒ chéng xù bù gōng kāi, jié guǒ zài gōng píng yě nán yǐ lìng rén xìn fú.', 'Jika prosedurnya tidak terbuka, hasil seadil apa pun sulit meyakinkan orang.']],
    [['公园和广场的公共性应该得到保障。', 'Gōng yuán hé guǎng chǎng de gōng gòng xìng yīng gāi dé dào bǎo zhàng.', 'Sifat publik taman dan alun-alun harus dijamin.'], ['地方感来自人们在一个地方长期的生活经验。', 'Dì fāng gǎn lái zì rén men zài yí gè dì fāng cháng qī de shēng huó jīng yàn.', 'Rasa tempat berasal dari pengalaman hidup jangka panjang di suatu tempat.'], ['绅士化提高了房价，也改变了社区的构成。', 'Shēn shì huà tí gāo le fáng jià, yě gǎi biàn le shè qū de gòu chéng.', 'Gentrifikasi menaikkan harga rumah dan juga mengubah komposisi komunitas.']],
    [['数字主权问题关系到一个国家对数据和平台的控制能力。', 'Shù zì zhǔ quán wèn tí guān xì dào yí gè guó jiā duì shù jù hé píng tái de kòng zhì néng lì.', 'Isu kedaulatan digital menyangkut kemampuan suatu negara mengendalikan data dan platform.'], ['算法治理的目标是让技术服务于公共利益。', 'Suàn fǎ zhì lǐ de mù biāo shì ràng jì shù fú wù yú gōng gòng lì yì.', 'Tujuan tata kelola algoritme adalah agar teknologi melayani kepentingan publik.'], ['通过数字人文方法，学者可以分析成千上万部古籍。', 'Tōng guò shù zì rén wén fāng fǎ, xué zhě kě yǐ fēn xī chéng qiān shàng wàn bù gǔ jí.', 'Melalui metode humaniora digital, akademisi dapat menganalisis ribuan kitab kuno.']],
    [['气候研究是一个典型的跨学科领域。', 'Qì hòu yán jiū shì yí gè diǎn xíng de kuà xué kē lǐng yù.', 'Riset iklim adalah bidang lintas disiplin yang khas.'], ['问题导向的研究更容易产生社会影响。', 'Wèn tí dǎo xiàng de yán jiū gèng róng yì chǎn shēng shè huì yǐng xiǎng.', 'Penelitian berorientasi masalah lebih mudah menghasilkan dampak sosial.'], ['定量和定性的方法融合，使研究结论更加全面。', 'Dìng liàng hé dìng xìng de fāng fǎ róng hé, shǐ yán jiū jié lùn gèng jiā quán miàn.', 'Integrasi metode kuantitatif dan kualitatif membuat kesimpulan riset lebih menyeluruh.']],
    [['违反学术规范的行为会损害整个学术共同体的声誉。', 'Wéi fǎn xué shù guī fàn de xíng wéi huì sǔn hài zhěng gè xué shù gòng tóng tǐ de shēng yù.', 'Pelanggaran norma akademik merusak reputasi seluruh komunitas akademik.'], ['学术自由也意味着承担相应的学术责任。', 'Xué shù zì yóu yě yì wèi zhe chéng dān xiāng yìng de xué shù zé rèn.', 'Kebebasan akademik juga berarti memikul tanggung jawab akademik yang sepadan.'], ['公共知识分子需要在专业性和通俗性之间保持平衡。', 'Gōng gòng zhī shi fēn zǐ xū yào zài zhuān yè xìng hé tōng sú xìng zhī jiān bǎo chí píng héng.', 'Intelektual publik perlu menyeimbangkan kedalaman keahlian dan bahasa yang mudah dipahami.']],
    [['研究问题越具体，研究设计就越容易展开。', 'Yán jiū wèn tí yuè jù tǐ, yán jiū shè jì jiù yuè róng yì zhǎn kāi.', 'Semakin spesifik pertanyaan penelitian, semakin mudah rancangan penelitian dikembangkan.'], ['学术论文的结构一般包括引言、方法、结果和讨论。', 'Xué shù lùn wén de jié gòu yì bān bāo kuò yǐn yán, fāng fǎ, jié guǒ hé tǎo lùn.', 'Struktur makalah akademik umumnya meliputi pendahuluan, metode, hasil, dan pembahasan.'], ['一项研究的理论贡献，在于它改变了我们理解问题的方式。', 'Yí xiàng yán jiū de lǐ lùn gòng xiàn, zài yú tā gǎi biàn le wǒ men lǐ jiě wèn tí de fāng shì.', 'Kontribusi teoretis suatu penelitian terletak pada bagaimana ia mengubah cara kita memahami masalah.']],
  ],
};
